css:
.fx-dot{position:relative;min-height:100vh;display:grid;place-items:center;text-align:center;padding:2em;overflow:hidden;isolation:isolate;background:var(--surface)}
.fx-dot .dots,.fx-dot .glow{position:absolute;inset:0;z-index:-1;pointer-events:none}
.fx-dot .dots{background-image:radial-gradient(color-mix(in srgb,var(--text) 26%,transparent) 1.3px,transparent 1.6px);background-size:26px 26px;-webkit-mask-image:radial-gradient(ellipse 75% 70% at 50% 50%,#000 30%,transparent 100%);mask-image:radial-gradient(ellipse 75% 70% at 50% 50%,#000 30%,transparent 100%)}
.fx-dot .glow{overflow:hidden}
.fx-dot .glow i{position:absolute;width:min(70vmin,520px);aspect-ratio:1;left:calc(50% - min(35vmin,260px));top:calc(50% - min(35vmin,260px));background-image:radial-gradient(var(--accent) 1.7px,transparent 2px);background-size:26px 26px;-webkit-mask-image:radial-gradient(circle,#000,transparent 68%);mask-image:radial-gradient(circle,#000,transparent 68%);animation:fxdotmove calc(14s/var(--speed)) ease-in-out infinite alternate}
.fx-dot .glow i::after{content:"";position:absolute;inset:20%;border-radius:50%;background:radial-gradient(circle,color-mix(in srgb,var(--accent) 22%,transparent),transparent 70%)}
.fx-dot .in{display:grid;gap:1.1em;justify-items:center;max-width:680px}
.fx-dot .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-dot h1{font-size:clamp(2.4em,7vw,4.8em)}.fx-dot p{opacity:.7;font-size:1.12em;max-width:44ch}
.fx-dot .row{display:flex;gap:.7em;flex-wrap:wrap;justify-content:center;margin-top:.3em}
.fx-dot .b{padding:.85em 1.5em;border-radius:var(--radius);font-weight:700;text-decoration:none;border:1.5px solid var(--text);color:var(--text);transition:all calc(.25s/var(--speed))}
.fx-dot .b.s{background:var(--text);color:var(--surface)}.fx-dot .b:hover{transform:translateY(-2px)}.fx-dot .b:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
@keyframes fxdotmove{0%{transform:translate(-28vw,-14vh)}50%{transform:translate(10vw,16vh)}100%{transform:translate(26vw,-8vh)}}
@media(prefers-reduced-motion:reduce){.fx-dot .glow i{animation:none}.fx-dot .b{transition:none}}

/* touch: :hover mirrored as .is-tap */
.fx-dot .b.is-tap{transform:translateY(-2px)}
